/**
 * Edit-modes graphic — a 3×3 grid of the editor's modes as line glyphs, the
 * first (Select) highlighted in accent. Glyphs are static line art; motion comes
 * from the section reveal. Theme vars from .nco-motion. Generated by a sub-agent,
 * integrated + simplified (dropped a fragile pathLength-on-group draw + a local
 * <style> block that would have clobbered the shared .m-draw class).
 */

type Cell = { id: string; label: string; glyph: JSX.Element };

const CELLS: Cell[] = [
  { id: 'select', label: 'SELECT', glyph: <polyline points="20,12 20,38 26,32 30,42 33,41 29,31 36,31" /> },
  { id: 'spacing', label: 'SPACING', glyph: (
    <>
      <rect x={14} y={18} width={24} height={16} />
      <line x1={8} y1={18} x2={8} y2={34} /><line x1={8} y1={18} x2={11} y2={18} /><line x1={8} y1={34} x2={11} y2={34} />
      <line x1={44} y1={18} x2={44} y2={34} /><line x1={44} y1={18} x2={41} y2={18} /><line x1={44} y1={34} x2={41} y2={34} />
    </>
  ) },
  { id: 'size', label: 'SIZE', glyph: (
    <>
      <rect x={12} y={12} width={28} height={28} />
      <line x1={34} y1={34} x2={44} y2={44} /><polyline points="38,44 44,44 44,38" />
    </>
  ) },
  { id: 'type', label: 'TYPE', glyph: (
    <>
      <line x1={16} y1={14} x2={36} y2={14} /><line x1={26} y1={14} x2={26} y2={42} /><line x1={21} y1={42} x2={31} y2={42} />
    </>
  ) },
  { id: 'color', label: 'COLOR', glyph: (
    <path d="M26,14 C26,14 14,28 14,34 C14,40.6 19.4,46 26,46 C32.6,46 38,40.6 38,34 C38,28 26,14 26,14 Z" />
  ) },
  { id: 'position', label: 'POSITION', glyph: (
    <>
      <circle cx={26} cy={28} r={4} />
      <line x1={26} y1={14} x2={26} y2={20} /><polyline points="23,17 26,14 29,17" />
      <line x1={26} y1={36} x2={26} y2={42} /><polyline points="23,39 26,42 29,39" />
      <line x1={12} y1={28} x2={18} y2={28} /><polyline points="15,25 12,28 15,31" />
      <line x1={34} y1={28} x2={40} y2={28} /><polyline points="37,25 40,28 37,31" />
    </>
  ) },
  { id: 'reorder', label: 'REORDER', glyph: (
    <>
      <line x1={16} y1={20} x2={36} y2={20} /><line x1={16} y1={28} x2={36} y2={28} /><line x1={16} y1={36} x2={36} y2={36} />
      <line x1={42} y1={22} x2={42} y2={34} /><polyline points="39,25 42,22 45,25" /><polyline points="39,31 42,34 45,31" />
    </>
  ) },
  { id: 'text', label: 'TEXT', glyph: (
    <>
      <line x1={26} y1={14} x2={26} y2={42} /><line x1={22} y1={14} x2={30} y2={14} /><line x1={22} y1={42} x2={30} y2={42} /><line x1={22} y1={28} x2={26} y2={28} />
    </>
  ) },
  { id: 'media', label: 'MEDIA', glyph: (
    <>
      <rect x={11} y={16} width={30} height={24} /><polyline points="11,34 18,26 24,32 30,24 41,40" /><circle cx={35} cy={23} r={3} />
    </>
  ) },
];

const SIZE = 160;
const COLS = 3;

export default function EditModes() {
  return (
    <svg
      viewBox="0 0 480 480"
      width="100%"
      height="100%"
      role="img"
      aria-label="Edit modes: select, spacing, size, type, color, position, reorder, text, media"
      preserveAspectRatio="xMidYMid meet"
      style={{ display: 'block' }}
    >
      {CELLS.map((cell, i) => {
        const col = i % COLS;
        const row = Math.floor(i / COLS);
        const cx = col * SIZE;
        const cy = row * SIZE;
        const active = i === 0;
        const stroke = active ? 'var(--m-accent)' : 'var(--m-line-2)';
        const fill = cell.id === 'color' ? 'var(--m-accent)' : 'none';
        return (
          <g key={cell.id} transform={`translate(${cx}, ${cy})`} aria-hidden="true">
            <rect x={0.5} y={0.5} width={SIZE - 1} height={SIZE - 1} fill="none" stroke={active ? 'var(--m-accent)' : 'var(--m-line)'} strokeWidth={active ? 1 : 0.75} />
            <g transform={`translate(${SIZE / 2 - 26}, ${SIZE / 2 - 34})`} fill={fill} stroke={stroke} strokeWidth={1.6} strokeLinecap="round" strokeLinejoin="round">
              {cell.glyph}
            </g>
            <text x={SIZE / 2} y={SIZE - 18} textAnchor="middle" fontFamily="var(--m-mono)" fontSize={10} letterSpacing={1} fill={active ? 'var(--m-accent)' : 'var(--m-fg-dim)'}>{cell.label}</text>
          </g>
        );
      })}
    </svg>
  );
}
